-- READ-ONLY diagnostic projection only. Nearest-grid membership is not a timestamp correction.
WITH raw AS (
 SELECT a.dateTime ts,a.interval iv FROM old_weewx.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL
 UNION
 SELECT a.dateTime ts,a.interval iv FROM weewx_WH1080.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL
), u AS (SELECT ts,MIN(iv) interval_min,COUNT(DISTINCT iv) interval_variants FROM raw GROUP BY ts), slot_groups AS (SELECT FLOOR((u.ts+150)/300)*300 nearest_5m_epoch,u.interval_min,u.interval_variants,COUNT(*) source_timestamps,MAX(r.dateTime IS NOT NULL) reconstruction_nearest_row FROM u LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=FLOOR((u.ts+150)/300)*300 GROUP BY nearest_5m_epoch,u.interval_min,u.interval_variants) SELECT interval_min,interval_variants,reconstruction_nearest_row,source_timestamps,COUNT(*) projected_grid_slots,SUM(source_timestamps) source_timestamps_in_groups FROM slot_groups GROUP BY interval_min,interval_variants,reconstruction_nearest_row,source_timestamps ORDER BY interval_min,interval_variants,reconstruction_nearest_row,source_timestamps;
